  function addSettings(){var target=document.querySelector("#settings .setting-card .notification-options");if(target)target.insertAdjacentHTML("beforeend",'<label><input type="checkbox" data-life-alert="course"><span data-lkey="courseDeadlines"></span></label><label><input type="checkbox" data-life-alert="workout"><span data-lkey="workoutReminders"></span></label><label><input type="checkbox" data-life-alert="habit"><span data-lkey="habitReminders"></span></label>');try{lifePrefs=Object.assign(lifePrefs,JSON.parse(localStorage.getItem("mg_exec_life_preferences_v4")||"{}"));}catch(_){}}
