  function buildMobileNav(){var n=document.getElementById("lifeMobileNav");if(!n)return;n.innerHTML='<button data-route="dash"><span>⌂</span>'+tx("today")+'</button><button data-route="work"><span>▦</span>'+tx("work")+'</button><button data-route="learning"><span>▤</span>'+tx("learning")+'</button><button data-route="health"><span>♡</span>'+tx("health")+'</button><button id="mobileMore"><span>☰</span>'+tx("mobileMore")+'</button>';n.querySelectorAll("[data-route]").forEach(function(b){b.addEventListener("click",function(){route(b.dataset.route);});});n.querySelector("#mobileMore").addEventListener("click",function(){appRoot.classList.toggle("mobile-open");});}
  function route(id){var target=document.getElementById(id);if(!target)return;document.querySelectorAll(".life-main .view").forEach(function(x){x.classList.remove("on");});target.classList.add("on");document.querySelectorAll("#lifeNav [data-route]").forEach(function(x){x.classList.toggle("active",x.dataset.route===id||(id==="projects"||id==="tasks")&&x.dataset.route==="work");});document.querySelectorAll("#lifeMobileNav [data-route]").forEach(function(x){x.classList.toggle("active",x.dataset.route===id||(id==="projects"||id==="tasks")&&x.dataset.route==="work");});appRoot.classList.remove("mobile-open");if(id==="settings")renderProfile();refresh();}
  function localize(){document.querySelectorAll("[data-lkey]").forEach(function(el){var key=el.dataset.lkey;if(!L[lang()][key]&&!app.t(key))return;var label=el.matches("label");if(label){var span=el.querySelector("span[data-local-label]");if(!span){span=document.createElement("span");span.dataset.localLabel="1";el.insertBefore(span,el.firstChild);}span.textContent=tx(key);}else if(el.matches("input,textarea"))el.placeholder=tx(key);else el.textContent=tx(key);});document.querySelectorAll("[data-category]").forEach(function(el){el.textContent=tx(el.dataset.category);});document.getElementById("lifeSearch").placeholder=tx("search");document.querySelectorAll("#courseStatus option").forEach(function(o){o.textContent=tx(o.value==="completed"?"completed":o.value==="in_progress"?"inProgress":"notStarted");});document.querySelectorAll("#habitFrequency option").forEach(function(o){o.textContent=tx(o.value);});var ct=document.getElementById("courseDialogTitle"),wt=document.getElementById("workoutDialogTitle"),mt=document.getElementById("mealDialogTitle"),ht=document.getElementById("habitDialogTitle");if(ct)ct.textContent=tx("createCourse");if(wt)wt.textContent=tx("createWorkout");if(mt)mt.textContent=tx("createMeal");if(ht)ht.textContent=tx("createHabit");buildMobileNav();}
  function refresh(){if(!appRoot)return;app.render();localize();renderProfile();renderLife();processLifeAlerts();app.renderAlertControls();renderLife();}
  function renderProfile(){var d=db(),p=d.profile||{},name=p.displayName||tx("genericUser"),title=p.title||tx("userDefault"),avatar=p.avatar||"";document.getElementById("profileNameSidebar").textContent=name;document.getElementById("profileTitleSidebar").textContent=title;document.getElementById("profileNameHeader").textContent=name;var initial=(p.displayName||"M").trim().charAt(0)||"M";["profileAvatarSidebar","profileAvatarHeader"].forEach(function(id){var el=document.getElementById(id);el.innerHTML=avatar?'<img src="'+esc(avatar)+'" alt="">':esc(initial);});document.getElementById("profileDisplayName").value=p.displayName||"";document.getElementById("profileTitle").value=p.title||"";document.getElementById("profileAvatarInput").value=p.avatar||"";var h=new Date().getHours(),key=h<12?"goodMorning":h<18?"goodAfternoon":"goodEvening";document.getElementById("greetingText").textContent=tx(key);document.getElementById("greetingName").textContent=p.displayName||tx("genericUser");var d0=new Date();document.getElementById("todayDate").textContent=new Intl.DateTimeFormat(lang()==="ar"?"ar-SA":"en-GB",{weekday:"long",day:"numeric",month:"long"}).format(d0);}
